This is the script that makes my ground. Add a ball that drops from above onto it.

using UnityEngine;
using Unity.U2D.Physics;

public class GroundSpawner : MonoBehaviour
{
    private void Start()
    {
        var groundDef = PhysicsBodyDefinition.defaultDefinition;
        groundDef.type = PhysicsBody.BodyType.Static;
        var ground = PhysicsWorld.defaultWorld.CreateBody(groundDef);
        ground.CreateShape(PolygonGeometry.CreateBox(new Vector2(16f, 1f)));
    }
}

