using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private void FixedUpdate()
    {
        var body = GetComponent<Rigidbody2D>();
        body.linearVelocity = new Vector2(5f, body.linearVelocity.y);
    }
}
